"use client";

import React, { useState } from "react";
import { AlertTriangle, Copy, Check } from "lucide-react";

export function APIErrorStateCard() {
  const [copied, setCopied] = useState(false);
  const backtrace = "Error: REST endpoints validation failed at apps/docs/src/components/ui/APIErrorStateCard.tsx:42";

  const triggerCopy = () => {
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-red-500/20 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5">
          <AlertTriangle className="w-4 h-4 text-red-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-red-400">API Crash Incident</span>
        </div>
        <button 
          onClick={triggerCopy}
          className="p-1.5 rounded-lg bg-secondary/30 hover:bg-secondary/60 text-muted-foreground"
        >
          {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
        </button>
      </div>

      <div className="min-h-16 bg-black/40 border border-white/[0.04] p-3 rounded-xl font-mono text-[10px] text-red-300/80 leading-normal mb-3 overflow-hidden text-ellipsis">
        {backtrace}
      </div>

      <p className="text-[10px] text-muted-foreground/60">Please review standard CORS variables inside active configuration files.</p>
    </div>
  );
}
